        dp[0] = 0;
        for (int i = 1; i <= bound; i++) {
            for (int c : coins) {
                if (c <= i && dp[i-c] != INT_MAX)
                    dp[i] = min(dp[i], dp[i-c] + 1);
            }
        }

        for (int i = 1; i <= bound; i++) {
            // Greedy
            int rem = i, cnt = 0;
            for (int c : coins) {
                cnt += rem / c;
                rem %= c;
            }
            if (cnt != dp[i]) { greedyWorks = false; break; }
