#include <bits/stdc++.h>
using namespace std;

/*
This problem is the classic "canonical coin system" check for systems that
must be able to pay every positive integer amount.

Key facts:
- To be able to pay every positive integer amount, the smallest coin must be 1.
- Let coins be sorted increasingly, with c[0] = 1.
- If all amounts up to S can be formed, then to avoid a gap the next coin c[i]
  must satisfy c[i] <= S + 1. Then all amounts up to S + c[i] become formable.
- Therefore, the system is satisfactory iff:
    c[0] = 1
    and for every i > 0: c[i] <= 1 + sum(c[0..i-1])

Input format assumed:
T
n
c1 c2 ... cn
(repeated T times)

Output:
For each test case:
YES  if satisfactory
NO   otherwise

This matches the standard criterion for whether no amount is impossible.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        int n;
        cin >> n;
        vector<long long> c(n);
        for (int i = 0; i < n; ++i) cin >> c[i];

        sort(c.begin(), c.end());

        bool ok = true;
        long long reach = 0; // all amounts in [1..reach] are formable

        for (int i = 0; i < n; ++i) {
            if (c[i] > reach + 1) {
                ok = false;
                break;
            }
            reach += c[i];
        }

        cout << (ok ? "YES" : "NO") << '\n';
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    return *(int*)a - *(int*)b;
}

int greedy(int amount, int coins[], int n) {
    int count = 0;
    for (int i = n - 1; i >= 0; i--) {
        count += amount / coins[i];
        amount %= coins[i];
    }
    return count;
}

int dp_min_coins(int amount, int coins[], int n) {
    int dp[amount + 1];
    dp[0] = 0;
    for (int i = 1; i <= amount; i++) {
        dp[i] = amount + 1;
        for (int j = 0; j < n; j++) {
            if (coins[j] <= i) {
                int sub = dp[i - coins[j]];
                if (sub != amount + 1 && sub + 1 < dp[i])
                    dp[i] = sub + 1;
            }
        }
    }
    return dp[amount];
}

int main() {
    int n;
    while (scanf("%d", &n) == 1) {
        int coins[n];
        for (int i = 0; i < n; i++) {
            scanf("%d", &coins[i]);
        }
        qsort(coins, n, sizeof(int), cmp);

        // Check completeness: smallest coin must be 1
        if (coins[0] != 1) {
            printf("not satisfactory\n");
            continue;
        }

        // Check canonicity up to limit
        int limit = coins[n-1] + coins[n-2]; // standard bound
        int canonical = 1;
        for (int amt = 1; amt <= limit; amt++) {
            int g = greedy(amt, coins, n);
            int opt = dp_min_coins(amt, coins, n);
            if (g != opt) {
                canonical = 0;
                break;
            }
        }

        if (canonical)
            printf("satisfactory\n");
        else
            printf("not satisfactory\n");
    }
    return 0;
}

