#define MAXV 10000

int coins[20], n;
int dp[MAXV+1];

int greedy_count(int amount) {
    int count = 0;
    for (int i = n-1; i >= 0; i--) {
        count += amount / coins[i];
        amount %= coins[i];
    }
    return (amount == 0) ? count : -1;
}

int main() {
    while (scanf("%d", &n) == 1) {
        for (int i = 0; i < n; i++) scanf("%d", &coins[i]);
        // sort coins
        for (int i = 0; i < n; i++)
            for (int j = i+1; j < n; j++)
                if (coins[i] > coins[j]) { int t = coins[i]; coins[i] = coins[j]; coins[j] = t; }

        int limit = MAXV;
        // DP for minimum coins
        dp[0] = 0;
        for (int i = 1; i <= limit; i++) dp[i] = 1000000;
        for (int i = 1; i <= limit; i++) {
            for (int j = 0; j < n; j++) {
                if (coins[j] <= i && dp[i - coins[j]] + 1 < dp[i])
                    dp[i] = dp[i - coins[j]] + 1;
            }
        }

        int all_payable = 1, greedy_ok = 1;
        for (int i = 1; i <= limit; i++) {
            if (dp[i] == 1000000) { all_payable = 0; break; }
        }

        if (all_payable) {
            for (int i = 1; i <= limit; i++) {
                int g = greedy_count(i);
                if (g == -1 || g != dp[i]) { greedy_ok = 0; break; }
            }
            if (greedy_ok) printf("Satisfactory\n");
            else printf("Unsatisfactory\n");
        } else {
            printf("Unsatisfactory\n");
        }
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int cmp_ll(const void *a, const void *b) {
    long long x = *(const long long *)a;
    long long y = *(const long long *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int T;
    if (scanf("%d", &T) != 1) return 0;

    while (T--) {
        int n;
        scanf("%d", &n);

        long long *a = (long long *)malloc((size_t)n * sizeof(long long));
        for (int i = 0; i < n; i++) scanf("%lld", &a[i]);

        qsort(a, n, sizeof(long long), cmp_ll);

        int ok = 1;
        if (a[0] != 1) {
            ok = 0;
        } else {
            long long reach = 1; /* we can make every value in [1, reach] */
            for (int i = 1; i < n; i++) {
                if (a[i] > reach + 1) {
                    ok = 0;
                    break;
                }
                reach += a[i];
            }
        }

        if (ok) printf("YES\n");
        else printf("NO\n");

        free(a);
    }

    return 0;
}

def solve():
    import sys
    input_data = sys.stdin.read().strip().split()
    t = int(input_data[0])
    idx = 1
    results = []

    for _ in range(t):
        n = int(input_data[idx]); idx += 1
        coins = list(map(int, input_data[idx:idx+n])); idx += n

        # Check completeness: must have coin 1
        if coins[0] != 1:
            results.append("not complete")
            continue

        # Check canonical (greedy optimal) up to bound = coins[-1] + coins[-2]
        bound = coins[-1] + coins[-2]

        # DP to find optimal number of coins for each amount up to bound
        INF = 10**9
        dp = [INF] * (bound + 1)
        dp[0] = 0
        for c in coins:
            for amount in range(c, bound + 1):
                if dp[amount - c] + 1 < dp[amount]:
                    dp[amount] = dp[amount - c] + 1

        greedy_ok = True
        for amount in range(1, bound + 1):
            # Greedy solution
            temp = amount
            greedy_count = 0
            for c in reversed(coins):
                if c <= temp:
                    cnt = temp // c
                    greedy_count += cnt
                    temp -= cnt * c
            if greedy_count != dp[amount]:
                greedy_ok = False
                break

        if greedy_ok:
            results.append("canonical")
        else:
            results.append("not canonical")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()

import java.util.*;

public class CoinSystem {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int testCases = sc.nextInt();
        while (testCases-- > 0) {
            int n = sc.nextInt();
            int[] coins = new int[n];
            for (int i = 0; i < n; i++) {
                coins[i] = sc.nextInt();
            }

            // Check if smallest coin is 1
            if (coins[0] != 1) {
                System.out.println("not complete");
                continue;
            }

            int maxCheck = coins[n-1] + coins[n-2]; // Upper bound for canonical check
            int[] dp = new int[maxCheck + 1];
            Arrays.fill(dp, Integer.MAX_VALUE / 2);
            dp[0] = 0;

            // DP for optimal coins
            for (int i = 1; i <= maxCheck; i++) {
                for (int c : coins) {
                    if (c <= i) {
                        dp[i] = Math.min(dp[i], dp[i - c] + 1);
                    }
                }
            }

            boolean canonical = true;
            // Check each coin for counterexample
            for (int cIndex = 0; cIndex < n && canonical; cIndex++) {
                int coin = coins[cIndex];
                // Try amounts from coin+1 to maxCheck
                for (int amount = coin + 1; amount <= maxCheck; amount++) {
                    // Greedy count for amount
                    int greedyCount = 0;
                    int remaining = amount;
                    for (int i = n - 1; i >= 0; i--) {
                        if (coins[i] <= remaining) {
                            int take = remaining / coins[i];
                            greedyCount += take;
                            remaining -= take * coins[i];
                        }
                    }
                    // If greedy is worse than optimal, not canonical
                    if (greedyCount > dp[amount]) {
                        canonical = false;
                        break;
                    }
                }
            }

            if (canonical) {
                System.out.println("canonical");
            } else {
                System.out.println("not canonical");
            }
        }
        sc.close();
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextLine()) {
            String line = sc.nextLine().trim();
            if (line.isEmpty()) continue;
            String[] parts = line.split("\\s+");
            int[] coins = new int[parts.length];
            for (int i = 0; i < parts.length; i++) coins[i] = Integer.parseInt(parts[i]);
            Arrays.sort(coins);

            int limit = 1000;
            // Check if all amounts 1..limit can be made
            boolean[] dp = new boolean[limit + 1];
            dp[0] = true;
            for (int i = 1; i <= limit; i++)
                for (int c : coins)
                    if (c <= i && dp[i - c]) { dp[i] = true; break; }

            boolean allMakeable = true;
            for (int i = 1; i <= limit; i++) if (!dp[i]) { allMakeable = false; break; }

            if (!allMakeable) { System.out.println("not satisfactory"); continue; }

            // Check greedy optimality
            int[] minCoins = new int[limit + 1];
            Arrays.fill(minCoins, Integer.MAX_VALUE / 2);
            minCoins[0] = 0;
            for (int i = 1; i <= limit; i++)
                for (int c : coins)
                    if (c <= i && minCoins[i - c] + 1 < minCoins[i])
                        minCoins[i] = minCoins[i - c] + 1;

            boolean greedyWorks = true;
            for (int i = 1; i <= limit; i++) {
                int rem = i, cnt = 0;
                for (int j = coins.length - 1; j >= 0 && rem > 0; j--)
                    while (rem >= coins[j]) { rem -= coins[j]; cnt++; }
                if (cnt != minCoins[i]) { greedyWorks = false; break; }
            }

            System.out.println(greedyWorks ? "satisfactory" : "not satisfactory");
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        int t;
        try {
            t = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        for (int tc = 1; tc <= t; tc++) {
            int n = fs.nextInt();
            long[] a = new long[n];
            for (int i = 0; i < n; i++) a[i] = fs.nextLong();

            boolean ok = true;

            // To pay every positive integer amount, first coin must be 1.
            if (a[0] != 1) ok = false;

            // For greedy to always work for all amounts, each coin must be
            // at most 1 + sum of all previous coins.
            long sum = a[0];
            for (int i = 1; i < n && ok; i++) {
                if (a[i] > sum + 1) {
                    ok = false;
                    break;
                }
                sum += a[i];
            }

            out.append("Case #").append(tc).append(": ")
               .append(ok ? "YES" : "NO").append('\n');
        }

        System.out.print(out.toString());
    }
